video.addEventListener('play',()=>{if(scene==='cook'){playing=true;render();}});video.addEventListener('pause',()=>{if(scene==='cook'){playing=false;render();}});video.addEventListener('loadedmetadata',render);video.addEventListener('error',()=>status('视频加载失败，请确认 assets/cooking.mp4 存在。动画场景仍可体验。'));video.addEventListener('timeupdate',()=>{if(scene!=='cook')return;if(loopStep&&video.currentTime>=loopStep.end)video.currentTime=loopStep.start;if(onceStep&&video.currentTime>=onceStep.end){video.pause();onceStep=null;status('这个片段已播放完毕。');}render();});video.addEventListener('ended',()=>{if(loopStep){seek(loopStep.start);setPlaying(true);}else{playing=false;render();}});
