function say(text){if(!('speechSynthesis'in window))return;stopSpeech();const token=speechToken;speaking=true;speechVolume=video.volume;video.volume=speechVolume*prefs.duck/100;clearTimeout(sessionTimer);if(recognition)try{recognition.abort();}catch{}const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=prefs.rate;const done=()=>{if(token!==speechToken)return;speaking=false;if(speechVolume!==null){video.volume=speechVolume;speechVolume=null;}if(micEnabled){armTimeout();scheduleRecognition();}};u.onend=done;u.onerror=done;speechSynthesis.speak(u);}
function scheduleRecognition(){clearTimeout(restartTimer);restartTimer=setTimeout(()=>{if(micEnabled&&!speaking&&!recognition)startRecognition();},350);}
function startRecognition(){const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){stopMic();status('此浏览器不支持语音识别。可使用文字输入或示例指令体验。');return;}const generation=micGeneration;const r=new R();recognition=r;r.lang='zh-CN';r.continuous=true;r.interimResults=true;r.onstart=()=>{if(generation!==micGeneration)return;micUI(awake?'正在听，请说…':'麦克风已开启，说“嘿 Nemo”');armTimeout();};r.onresult=e=>{if(generation!==micGeneration||speaking)return;armTimeout();for(let i=e.resultIndex;i<e.results.length;i++){const text=e.results[i][0].transcript.trim();$('voiceLabel').textContent=text||'正在听…';if(!e.results[i].isFinal)continue;const wake=/(嘿|嗨|hey)?\s*(nemo|尼莫|尼摩|妮莫)/i;if(!awake&&prefs.wake){if(!wake.test(text)){status('正在等待“嘿 Nemo”。也可在设置中关闭唤醒词。');continue;}awake=true;const rest=text.replace(wake,'').replace(/^[，,。\s]+/,'');command(rest||'嘿 Nemo');}else{command(text.replace(wake,''));}if(!prefs.continuous){stopMic();break;}}};r.onerror=e=>{if(generation!==micGeneration)return;if(e.error==='aborted'||e.error==='no-speech')return;const messages={'not-allowed':'麦克风权限未获允许。可在浏览器设置中授权，或使用文字输入。','audio-capture':'没有检测到可用麦克风。请连接麦克风后重试。',network:'语音服务连接失败。请检查网络，或使用文字输入。','service-not-allowed':'浏览器不允许语音服务。请使用文字输入。'};stopMic();status(messages[e.error]||'语音识别未完成，请重试。');};r.onend=()=>{if(generation!==micGeneration)return;recognition=null;if(micEnabled&&!speaking)scheduleRecognition();};try{r.start();}catch{recognition=null;stopMic();status('麦克风启动失败，请再次点击重试。');}}
$('mic').onclick=()=>{if(micEnabled){stopMic();stopSpeech();status('麦克风已关闭。');return;}stopSpeech();micEnabled=true;awake=!prefs.wake;status('请允许麦克风权限。浏览器可能联网处理语音；Nemo 不保存录音。');startRecognition();};
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopMic();stopSpeech();setPlaying(false);}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){stopMic();stopSpeech();}});
$('settingsFrame').addEventListener('load',()=> $('settingsFrame').contentWindow?.postMessage({type:'nemo-sync',value:prefs},location.origin));
applyPrefs();switchScene('cook');
